document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("stats-grid");n&&(n.innerHTML=CATARACT_INFO.quickStats.map(n=>`\n                <div class="stat-pill">\n                    <span class="stat-icon">${n.icon}</span>\n                    <span class="stat-value">${n.value}</span>\n                    <span class="stat-label">${n.label}</span>\n                </div>\n            `).join(""));const t=document.getElementById("history-content");t&&(t.innerHTML=`\n            <h3>${HISTORY_TEXT.title}</h3>\n            ${HISTORY_TEXT.paragraphs.map(n=>`<p>${n}</p>`).join("")}\n        `);const e=document.getElementById("cs-timeline");e&&(e.innerHTML=TIMELINE_EVENTS.map(n=>`\n                <div class="timeline-item">\n                    <div class="timeline-dot"></div>\n                    <div class="timeline-content">\n                        <span class="timeline-era">${n.era}</span>\n                        <h4>${n.title}</h4>\n                        <p>${n.description}</p>\n                    </div>\n                </div>\n            `).join(""));const i=document.getElementById("comparison-body");i&&(i.innerHTML=COMPARISON_ROWS.map(n=>`\n                <tr>\n                    <td>${n.aspect}</td>\n                    <td>${n.ancient}</td>\n                    <td>${n.modern}</td>\n                </tr>\n            `).join(""));const s=document.getElementById("significance-grid");s&&(s.innerHTML=SIGNIFICANCE_POINTS.map(n=>`\n                <div class="principle-card">\n                    <h4>${n.title}</h4>\n                    <p>${n.description}</p>\n                </div>\n            `).join(""));const a=document.getElementById("references-list");a&&(a.innerHTML=REFERENCES.map(n=>`<li><a href="${n.link}" target="_blank" rel="noopener">${n.text}</a></li>`).join(""))});